(window.CLAVE_TEST=window.CLAVE_TEST||{})[18]=[{"a":"Artículo 2 R1","q":[{"i":"18-51","p":"Código Penal. En materia de garantías penales y de la aplicación de la ley penal, señale la opción correcta","o":["No será castigada ninguna acción ni omisión que no esté prevista como delito por ley anterior a su perpetración","No será castigado ningún delito con pena que no se halle prevista por ley anterior a su perpetración. Carecerán, igualmente, de efectos retroactivos las leyes que establezcan medidas de seguridad","En caso de duda sobre la determinación de la Ley más favorable, será oído el reo","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>- Todas las afirmaciones son principios básicos de garantías penales."},{"i":"18-12","p":"Código Penal. De las garantías y de la aplicación de la ley penal. Tendrán efecto retroactivo:","o":["Las Leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.","Aquellas Leyes que favorezcan al reo siempre que al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.","Aquellas Leyes penales que favorezcan al reo, siempre que al entrar en vigor no hubiera recaído sentencia firme.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena</mark></span>Según el <span class=\"ref-norma\">art. 2 del Código Penal</span>: <span class=\"ref-concepto\">\"Tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1005","p":"Código Penal. Irretroactividad. Los hechos cometidos bajo la vigencia de una Ley temporal serán juzgados, sin embargo, conforme a ella:","o":["salvo que se disponga expresamente lo contrario.","en todo caso y sin excepción alguna.","salvo que la ley posterior sea más favorable al reo.","salvo que el Gobierno acuerde otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">salvo que se disponga expresamente lo contrario</mark></span>El <span class=\"ref-norma\">art. 2.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Los hechos cometidos bajo la vigencia de una Ley temporal serán juzgados, sin embargo, conforme a ella, salvo que se disponga expresamente lo contrario\"</span>. La excepción es que se disponga expresamente lo contrario, no la más favorable ni el acuerdo del Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1004","p":"Código Penal. Irretroactividad. Tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena. En caso de duda sobre la determinación de la Ley más favorable:","o":["será oído el Ministerio Fiscal.","será oído el reo.","decidirá el Tribunal Supremo.","se aplicará la ley vigente al tiempo de la sentencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">será oído el reo</mark></span>El <span class=\"ref-norma\">art. 2.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"En caso de duda sobre la determinación de la Ley más favorable, será oído el reo\"</span>. Ante la duda sobre cuál es la ley más favorable se oye al reo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5","q":[{"i":"18-107","p":"Ley Orgánica 10/1995, de 23 de noviembre, sobre el Código Penal. No hay pena sin:","o":["Dolo o imprudencia.","Culpabilidad objetiva.","Resultado lesivo.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dolo o imprudencia</mark></span>Según el <span class=\"ref-norma\">art. 5 del Código Penal</span>: <span class=\"ref-concepto\">\"No hay pena sin dolo o imprudencia\"</span> (verificado con el texto del temario oficial)."},{"i":"18-189","p":"Código Penal. De las garantías penales y de la aplicación de la ley penal. No hay pena sin:","o":["Dolo.","Imprudencia.","A y B son correctas.","Todas son incorrectas. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 5 del Código Penal</span>: <span class=\"ref-concepto\">\"No hay pena sin dolo o imprudencia\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1012","p":"Código Penal. Principio de culpabilidad. No hay pena sin:","o":["dolo o culpa grave.","dolo o imprudencia.","dolo, imprudencia o negligencia.","dolo e imprudencia concurrentes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dolo o imprudencia</mark></span>El <span class=\"ref-norma\">art. 5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"No hay pena sin dolo o imprudencia\"</span>. Principio de culpabilidad: dolo o imprudencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 8","q":[{"i":"18-248","p":"Código Penal. Concurso de normas. Los hechos susceptibles de ser calificados con arreglo a dos o más preceptos del Código, se castigarán observando, entre otras, la regla según la cual:","o":["El precepto especial se aplicará con preferencia al general.","El precepto general se aplicará con preferencia al especial.","El precepto subsidiario se aplicará con preferencia al principal.","El precepto penal más benigno excluirá a los que castiguen el hecho con pena mayor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El precepto especial se aplicará con preferencia al general</mark></span>El <span class=\"ref-norma\">art. 8.1.ª de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"ª El precepto especial se aplicará con preferencia al general\"</span>"},{"i":"18-109","p":"Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal. Los hechos susceptibles de ser calificados con arreglo a dos o más preceptos de este Código, y no comprendidos en los artículos 73 a 77, se castigarán observando las siguientes reglas: señale la incorrecta.","o":["El precepto general se aplicará con preferencia al especial.","El precepto subsidiario se aplicará sólo en defecto del principal, ya se declare expresamente dicha subsidiariedad, ya sea ésta tácitamente deducible.","El precepto penal más amplio o complejo absorberá a los que castiguen las infracciones consumidas en aquél.","En defecto de los criterios anteriores, el precepto penal más grave excluirá los que castiguen el hecho con pena menor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El precepto general se aplicará con preferencia al especial</mark></span>El precepto especial prevalece sobre el general, no al revés. Según el <span class=\"ref-norma\">art. 8 del Código Penal</span>: <span class=\"ref-concepto\">\"1.ª El precepto especial se aplicará con preferencia al general\"</span> (verificado con el texto del temario oficial)."},{"i":"18-202","p":"Código Penal. Los hechos susceptibles de ser calificados con arreglo a dos o más preceptos de este Código, y no comprendidos en esta ley, se castigarán con respecto a las siguientes reglas: señale la INCORRECTA.","o":["El precepto general se aplicará con preferencia al especial.","El precepto subsidiario se aplicará sólo en defecto del principal, ya se declare expresamente dicha subsidiariedad, ya sea ésta tácitamente deducible.","El precepto penal más amplio o complejo absorberá a los que castiguen las infracciones consumidas en aquél.","En defecto de otros criterios, el precepto penal más grave excluirá los que castiguen el hecho con pena menor. *"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El precepto general se aplicará con preferencia al especial.</mark></span><span class=\"ref-norma\">Art. 8 · De las Penas</span>. El precepto general se aplicará con preferencia al especial. (La regla correcta, según el Artículo 8 del Código Penal, es la contraria: el precepto especial se aplica con preferencia al general).*"},{"i":"18-ia-1016","p":"Código Penal. Concurso de normas. Los hechos susceptibles de ser calificados con arreglo a dos o más preceptos del Código, y no comprendidos en los artículos 73 a 77, se castigarán observando, entre otras, la regla según la cual:","o":["el precepto general se aplicará con preferencia al especial.","el precepto especial se aplicará con preferencia al general.","el precepto subsidiario se aplicará con preferencia al principal.","el precepto más antiguo se aplicará con preferencia al posterior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el precepto especial se aplicará con preferencia al general</mark></span>El <span class=\"ref-norma\">art. 8 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El precepto especial se aplicará con preferencia al general\"</span>. Regla 1.ª: lo especial prevalece sobre lo general. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1017","p":"Código Penal. Concurso de normas. Señale la INCORRECTA sobre las reglas del concurso de normas:","o":["El precepto subsidiario se aplicará siempre, aunque exista el principal, si es más favorable al reo.","El precepto penal más amplio o complejo absorberá a los que castiguen las infracciones consumidas en aquél.","En defecto de los criterios anteriores, el precepto penal más grave excluirá los que castiguen el hecho con pena menor.","El precepto subsidiario se aplicará sólo en defecto del principal, ya se declare expresamente dicha subsidiariedad, ya sea ésta tácitamente deducible."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El precepto subsidiario se aplicará siempre, aunque exista el principal, si es más favorable al reo</mark></span>El <span class=\"ref-norma\">art. 8 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El precepto subsidiario se aplicará sólo en defecto del principal, ya se declare expresamente dicha subsidiariedad, ya sea ésta tácitamente deducible\"</span>. El subsidiario se aplica sólo en defecto del principal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1018","p":"Código Penal. Concurso de normas. En defecto de los criterios de especialidad, subsidiariedad y consunción, el precepto penal más grave:","o":["se aplicará conjuntamente con los de pena menor, salvo que la autoridad judicial disponga otra cosa.","se aplicará solo si es más favorable al reo.","será sustituido por el precepto más benigno.","excluirá los que castiguen el hecho con pena menor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">excluirá los que castiguen el hecho con pena menor</mark></span>El <span class=\"ref-norma\">art. 8 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el precepto penal más grave excluirá los que castiguen el hecho con pena menor\"</span>. Regla 4.ª: alternatividad, el más grave excluye al de pena menor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 10","q":[{"i":"18-37","p":"Código Penal. Según establece el Código Penal, son delitos:","o":["Las acciones dolosas penadas por la ley","Las omisiones dolosas penadas por la ley","Las acciones imprudentes penadas por la ley","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>- El Código Penal considera delitos tanto acciones como omisiones, tanto dolosas como imprudentes, cuando están penadas por la ley."},{"i":"18-59","p":"Código Penal. Son delitos","o":["Las acciones y omisiones penadas por la ley","Las acciones y omisiones dolosas o imprudentes penadas por la ley","Las acciones dolosas o imprudentes penadas por la ley","Todas son incorrectas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las acciones y omisiones dolosas o imprudentes penadas por la ley</mark></span>- Los delitos pueden ser acciones u omisiones, tanto dolosas como imprudentes, penadas por la ley."},{"i":"18-147","p":"Código Penal. ¿Qué tipo de acciones y omisiones son consideradas delitos según la ley?","o":["Solo las acciones dolosas.","Solo las omisiones imprudentes.","Las acciones y omisiones que resulten en beneficio económico.","Las acciones y omisiones dolosas o imprudentes penadas por la ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las acciones y omisiones dolosas o imprudentes penadas por la ley.</mark></span>(Son delitos las acciones u omisiones dolosas o imprudentes penadas por la ley)."},{"i":"18-ia-1020","p":"Código Penal. Concepto de delito. Son delitos las acciones y omisiones:","o":["dolosas o imprudentes tipificadas por ley o reglamento.","dolosas o imprudentes penadas por la ley.","dolosas, imprudentes o negligentes penadas por la ley.","dolosas penadas por la ley, y las imprudentes en todo caso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dolosas o imprudentes penadas por la ley</mark></span>El <span class=\"ref-norma\">art. 10 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son delitos las acciones y omisiones dolosas o imprudentes penadas por la ley\"</span>. Definición de delito del art. 10. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 13","q":[{"i":"18-58","p":"Código Penal. De las penas y sus clases. La privación del derecho a conducir vehículos a motor y ciclomotores de tres meses a un año es una pena calificada como","o":["Grave","Menos grave","Leve","Ninguna es correcta"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Leve</mark></span>- La privación del derecho a conducir de 3 meses a 1 año se considera pena leve."},{"i":"18-48","p":"Código Penal. De los delitos. Cuando la pena, por su extensión, pueda considerarse a la vez, como leve y como menos grave, el delito se considerará, en todo caso, como","o":["Grave","Menos grave","Leve","B y C son correctas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Leve</mark></span>Grave y menos grave → grave; leve y menos grave → leve. Según el <span class=\"ref-norma\">art. 13 del Código Penal</span>: <span class=\"ref-concepto\">\"Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve\"</span> (verificado con el texto del temario oficial)."},{"i":"18-94","p":"Código Penal. De la infracción penal. Respecto de los delitos, indique la CORRECTA:","o":["Cuando la pena, por su extensión, pueda incluirse a la vez entre delito grave y menos grave, el delito se considerará, en todo caso, como menos grave","Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve","Cuando la pena, por su extensión, pueda incluirse entre delito grave y muy grave, el delito se considerará, en todo caso, como grave","A y B son correctas"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve</mark></span>Grave y menos grave → grave (no menos grave). Según el <span class=\"ref-norma\">art. 13 del Código Penal</span>: <span class=\"ref-concepto\">\"Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve\"</span> (verificado con el texto del temario oficial)."},{"i":"18-163","p":"Código Penal. De los delitos. ¿Cómo se considerará un delito cuando la pena pueda ser catalogada tanto como grave como menos grave?","o":["Como menos grave.","Como delito leve.","Como grave.","No se considerará delito."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Como grave.</mark></span>(Cuando pueda catalogarse como grave o menos grave, se considera grave)."},{"i":"18-ia-1024","p":"Código Penal. Clasificación de los delitos. Son delitos leves las infracciones que la ley castiga con pena leve. Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará:","o":["en todo caso, como menos grave.","en todo caso, como leve.","como leve o menos grave, a elección del Tribunal.","como menos grave, salvo que el reo sea primario."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en todo caso, como leve</mark></span>El <span class=\"ref-norma\">art. 13 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve\"</span>. En la frontera leve/menos grave gana leve; en la grave/menos grave gana grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1025","p":"Código Penal. Clasificación de los delitos. Cuando la pena, por su extensión, pueda incluirse a la vez entre las penas graves y las menos graves, el delito se considerará:","o":["en todo caso, como grave.","en todo caso, como menos grave.","como grave, salvo que concurran atenuantes.","como menos grave, por aplicación del principio favor rei."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en todo caso, como grave</mark></span>El <span class=\"ref-norma\">art. 13 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Cuando la pena, por su extensión, pueda incluirse a la vez entre las mencionadas en los dos primeros números de este artículo, el delito se considerará, en todo caso, como grave\"</span>. Si cabe como grave y menos grave, se considera grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14 R4 R5 R6","q":[{"i":"18-183","p":"Código penal. De la infracción penal. De los delitos. Señale la CORRECTA:","o":["Si el error sobre un hecho constitutivo de infracción penal, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada en todo caso como delito doloso.","Si el error sobre un hecho constitutivo de infracción penal, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción no será castigada.","Si el error sobre un hecho constitutivo de infracción penal, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada, en su caso, como imprudente.","Si el error sobre un hecho constitutivo de infracción penal, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada con la pena inferior en uno o dos grados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si el error sobre un hecho constitutivo de infracción penal, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada, en su caso, como imprudente</mark></span>Según el <span class=\"ref-norma\">art. 14 del Código Penal</span>: <span class=\"ref-concepto\">\"Si el error, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada, en su caso, como imprudente\"</span> (verificado con el texto del temario oficial)."}]},{"a":"TENTATIVA · Art. 16 CP","q":[{"i":"18-ia-1030","p":"Código Penal. Tentativa. Hay tentativa cuando el sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado, y sin embargo éste no se produce:","o":["por la intervención de la autoridad.","por causas dependientes de la voluntad del autor, previo informe de la unidad policial competente.","por la resistencia de la víctima.","por causas independientes de la voluntad del autor."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por causas independientes de la voluntad del autor</mark></span>El <span class=\"ref-norma\">art. 16.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"y sin embargo éste no se produce por causas independientes de la voluntad del autor\"</span>. El resultado no se produce por causas independientes de la voluntad del autor. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1031","p":"Código Penal. Tentativa. Quedará exento de responsabilidad penal por el delito intentado quien evite voluntariamente la consumación, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado, sin perjuicio de la responsabilidad en que pudiera haber incurrido:","o":["por los actos preparatorios, si éstos fueren constitutivos de conspiración.","por los actos ejecutados, cualquiera que sea su naturaleza.","por los actos ejecutados, si éstos fueren ya constitutivos de otro delito.","por la tentativa, que se castigará con la pena inferior en un grado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por los actos ejecutados, si éstos fueren ya constitutivos de otro delito</mark></span>El <span class=\"ref-norma\">art. 16.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"sin perjuicio de la responsabilidad en que pudiera haber incurrido por los actos ejecutados, si éstos fueren ya constitutivos de otro delito\"</span>. La exención no alcanza a los actos ya constitutivos de otro delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1032","p":"Código Penal. Tentativa. Cuando en un hecho intervengan varios sujetos, quedarán exentos de responsabilidad penal aquél o aquéllos que desistan de la ejecución ya iniciada, e impidan o intenten impedir, __________, la consumación:","o":["total, plena y eficazmente","seria, firme y decididamente","voluntaria, expresa y activamente","inmediata, seria y eficazmente"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seria, firme y decididamente</mark></span>El <span class=\"ref-norma\">art. 16.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"e impidan o intenten impedir, seria, firme y decididamente, la consumación\"</span>. Se exige impedir o intentar impedir seria, firme y decididamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 17 R8 R9 R10","q":[{"i":"18-ia-1033","p":"Código Penal. Conspiración y proposición. La conspiración existe cuando:","o":["dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.","dos o más personas se conciertan para la ejecución de un delito, sin resolver ejecutarlo.","el que ha resuelto cometer un delito invita a otra u otras personas a participar en él.","tres o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo</mark></span>El <span class=\"ref-norma\">art. 17.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La conspiración existe cuando dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo\"</span>. Conspiración: concierto de dos o más personas y resolución de ejecutarlo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-250","p":"Código Penal. Conspiración y proposición. La proposición existe cuando:","o":["Dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo, en los términos que determine la ley orgánica correspondiente.","Se incita directamente por medio de la imprenta a la perpetración de un delito.","El que ha resuelto cometer un delito invita a otra u otras personas a participar en él.","El sujeto da principio a la ejecución del delito directamente por hechos exteriores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El que ha resuelto cometer un delito invita a otra u otras personas a participar en él</mark></span>El <span class=\"ref-norma\">art. 17.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La proposición existe cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él\"</span>"},{"i":"18-ia-1034","p":"Código Penal. Conspiración y proposición. La proposición existe cuando:","o":["dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.","se incita directamente a la perpetración de un delito ante una concurrencia de personas.","el que ha concebido un delito propone a otra persona su ejecución material por precio.","el que ha resuelto cometer un delito invita a otra u otras personas a participar en él."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el que ha resuelto cometer un delito invita a otra u otras personas a participar en él</mark></span>El <span class=\"ref-norma\">art. 17.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La proposición existe cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él\"</span>. La proposición es la invitación del que ya ha resuelto delinquir. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1035","p":"Código Penal. Conspiración y proposición. La conspiración y la proposición para delinquir sólo se castigarán:","o":["cuando el delito proyectado sea grave.","cuando se haya iniciado la ejecución del delito.","en los casos especialmente previstos en la ley.","en todo caso cuando el delito proyectado sea doloso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en los casos especialmente previstos en la ley</mark></span>El <span class=\"ref-norma\">art. 17.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La conspiración y la proposición para delinquir sólo se castigarán en los casos especialmente previstos en la ley\"</span>. Punibles solo en los casos especialmente previstos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 18 R11 R12 R13","q":[{"i":"18-ia-1036","p":"Código Penal. Provocación y apología. La provocación existe cuando directamente se incita por medio de la imprenta, la radiodifusión o cualquier otro medio de eficacia semejante, que facilite la publicidad, o ante una concurrencia de personas, a:","o":["la comisión de un delito grave.","la perpetración de un delito.","la concertación de una conspiración.","la realización de actos preparatorios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la perpetración de un delito</mark></span>El <span class=\"ref-norma\">art. 18.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"o ante una concurrencia de personas, a la perpetración de un delito\"</span>. La provocación incita directamente a perpetrar un delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-165","p":"Código Penal. De los delitos. ¿Cuál de las siguientes opciones describe mejor la situación en la que la apología se considera delictiva?","o":["Cuando se realiza sin intención de incitar a un delito.","Cuando se hace en privado y sin alarde de publicidad.","Cuando por su naturaleza y circunstancias constituye una incitación directa a cometer un delito.","Cuando se realiza en cualquier contexto y circunstancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando por su naturaleza y circunstancias constituye una incitación directa a cometer un delito.</mark></span>(La apología es delictiva cuando constituye incitación directa a delinquir)."},{"i":"18-ia-1037","p":"Código Penal. Provocación y apología. Es apología, a los efectos del Código, la exposición, ante una concurrencia de personas o por cualquier medio de difusión, de ideas o doctrinas que ensalcen el crimen o enaltezcan a su autor. La apología sólo será delictiva:","o":["como forma de provocación y si por su naturaleza y circunstancias constituye una incitación directa a cometer un delito.","como forma de conspiración y si se difunde por medios de comunicación social, sin perjuicio de lo previsto en la normativa vigente.","en todo caso, siempre que se difunda ante una concurrencia de personas.","como forma de provocación y si el delito llega a perpetrarse."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como forma de provocación y si por su naturaleza y circunstancias constituye una incitación directa a cometer un delito</mark></span>El <span class=\"ref-norma\">art. 18.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La apología sólo será delictiva como forma de provocación y si por su naturaleza y circunstancias constituye una incitación directa a cometer un delito\"</span>. Solo es delictiva como provocación y si hay incitación directa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-118","p":"Código Penal. ¿En qué circunstancias se castiga la provocación?","o":["Exclusivamente los casos en que la Ley así lo prevea.","Siempre que se realice en público.","Solo cuando no hay seguimiento de perpetración del delito.","Cuando se realiza a través de medios de comunicación masiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Exclusivamente los casos en que la Ley así lo prevea.</mark></span>(La provocación solo se castiga cuando la Ley lo prevé expresamente)."}]},{"a":"Artículo 23","q":[{"i":"18-44","p":"Código Penal. De la circunstancia mixta de parentesco. Es circunstancia que puede ______ la responsabilidad, según la naturaleza, los motivos y los efectos del delito, ser o haber sido el agraviado cónyuge o persona que esté o haya estado ligada de forma estable por análoga relación de afectividad, o ser ascendiente, descendiente o hermano por naturaleza o adopción del ofensor o de su cónyuge o conviviente","o":["Atenuar o agravar","Atenuar y agravar","Solo agravar, nunca atenuar.","Agravar y controlar"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Atenuar o agravar</mark></span>- El parentesco puede atenuar o agravar la responsabilidad según las circunstancias."},{"i":"18-212","p":"Código Penal. Es circunstancia que puede ______ la responsabilidad, según la naturaleza, los motivos y los efectos del delito, ser o haber sido el agraviado cónyuge o persona que esté o haya estado ligada de forma estable por análoga relación de afectividad, o ser ascendiente, descendiente o hermano por naturaleza o adopción del ofensor o de su cónyuge o conviviente. Indique la que sea CORRECTA:","o":["Exonerar.","Compensar","Atenuar o agravar.","Todas las anteriores son respuestas correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Atenuar o agravar.</mark></span><span class=\"ref-norma\">Art. 23 · De las Penas</span>. (El parentesco es una circunstancia mixta, según el Artículo 23 del CP, que puede atenuar o agravar la responsabilidad)."},{"i":"18-ia-1067","p":"Código Penal. Circunstancia mixta de parentesco. Es circunstancia que puede atenuar o agravar la responsabilidad, según la naturaleza, los motivos y los efectos del delito, ser o haber sido el agraviado cónyuge o persona que esté o haya estado ligada de forma estable por análoga relación de afectividad, o ser ascendiente, descendiente o hermano:","o":["por naturaleza del ofensor, de su cónyuge o conviviente.","por naturaleza, adopción o afinidad del ofensor.","por naturaleza o adopción del ofensor o de su cónyuge o conviviente.","por naturaleza o adopción del ofensor, con exclusión de su cónyuge, previo informe de la unidad policial competente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por naturaleza o adopción del ofensor o de su cónyuge o conviviente</mark></span>El <span class=\"ref-norma\">art. 23 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ascendiente, descendiente o hermano por naturaleza o adopción del ofensor o de su cónyuge o conviviente\"</span>. Parentesco por naturaleza o adopción del ofensor o de su cónyuge o conviviente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-85","p":"Código Penal. De la infracción penal. De las circunstancias que atenúan la responsabilidad criminal. Son siempre circunstancias atenuantes: señale la INCORRECTA","o":["La de obrar por causas o estímulos tan poderosos que hayan producido arrebato, obcecación u otro estado pasional de entidad semejante","La de haber procedido el culpable a reparar el daño ocasionado a la víctima, o disminuir sus efectos, en cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral","La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa","Ser o haber sido el agraviado cónyuge o persona que esté o haya estado ligada de forma estable por análoga relación de afectividad, o ser ascendiente, descendiente o hermano por naturaleza o adopción del ofensor o de su cónyuge o conviviente"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ser o haber sido el agraviado cónyuge o persona que esté o haya estado ligada de forma estable por análoga relación de afectividad, o ser a…</mark></span>- El parentesco es circunstancia mixta que puede atenuar o agravar, no siempre atenuante."},{"i":"18-194","p":"Código Penal. De la circunstancia mixta de parentesco. Esta circunstancia:","o":["Puede agravar la responsabilidad, solamente.","Puede atenuar la responsabilidad, en cualquier caso.","Puede atenuar o agravar la responsabilidad.","Puede hacer que la responsabilidad sea un eximente. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Puede atenuar o agravar la responsabilidad.</mark></span><span class=\"ref-norma\">Art. 23 · De las Circunstancias que Modifican la Responsabilidad Criminal</span>. Puede atenuar o agravar la responsabilidad. (El parentesco es una circunstancia mixta, según el Artículo 23 del Código Penal, que puede actuar como atenuante o agravante dependiendo de la naturaleza del delito).*"}]},{"a":"Artículo 28 R15 R16","q":[{"i":"18-56","p":"Código Penal. De las personas criminalmente responsables de los delitos. Son considerados autores:","o":["Quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento.","Los que inducen directamente a otro u otros a ejecutarlo.","Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado.","Todas son correctas"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 28 del Código Penal</span>: <span class=\"ref-concepto\">\"Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento. También serán considerados autores: a) Los que inducen directamente a otro u otros a ejecutarlo. b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado\"</span> (verificado con el texto del temario oficial)."},{"i":"18-126","p":"Código Penal. De las personas criminalmente responsables de los delitos. Son autores quienes realizan el hecho:","o":["Por sí solos.","Conjuntamente.","Por medio de otro del que se sirven como instrumento.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 28 del Código Penal</span>: <span class=\"ref-concepto\">\"Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento\"</span> (verificado con el texto del temario oficial)."},{"i":"18-204","p":"Código Penal. Son autores:","o":["Quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento.","Los que inducen directamente a otro u otros a ejecutarlo.","Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado.","Todas son correctas. *"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas. *</mark></span>Según el <span class=\"ref-norma\">art. 28 del Código Penal</span>: <span class=\"ref-concepto\">\"Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento. También serán considerados autores: a) Los que inducen directamente a otro u otros a ejecutarlo. b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado\"</span> (verificado con el texto del temario oficial)."},{"i":"18-206","p":"Código Penal. Son autores:","o":["Quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento.","Los que inducen directamente a otro u otros a ejecutarlo.","Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 28 del Código Penal</span>: <span class=\"ref-concepto\">\"Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento. También serán considerados autores: a) Los que inducen directamente a otro u otros a ejecutarlo. b) Los que cooperan a su ejecución con un acto sin el cual no se habría efectuado\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1102","p":"Código Penal. Autores. Son autores quienes realizan el hecho:","o":["por sí solos o conjuntamente con otro u otros que cooperan en su ejecución.","por sí solos o por medio de otro que actúa bajo su dirección y control.","por sí solos, conjuntamente o por medio de otro, aunque éste actúe con dolo, en los términos que se determinen reglamentariamente.","por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento</mark></span>El <span class=\"ref-norma\">art. 28 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento\"</span>. Autoría directa, coautoría y autoría mediata. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 29 ✱","q":[{"i":"18-ia-1105","p":"Código Penal. Cómplices. Son cómplices los que, no hallándose comprendidos en el artículo anterior, cooperan a la ejecución del hecho con actos:","o":["anteriores o simultáneos.","anteriores o posteriores.","simultáneos o posteriores.","anteriores, simultáneos o posteriores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">anteriores o simultáneos</mark></span>El <span class=\"ref-norma\">art. 29 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son cómplices los que, no hallándose comprendidos en el artículo anterior, cooperan a la ejecución del hecho con actos anteriores o simultáneos\"</span>. Actos anteriores o simultáneos; los posteriores no son complicidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-252","p":"Código Penal. Cómplices. Son cómplices los que, no hallándose comprendidos entre los autores:","o":["Cooperan a la ejecución del hecho con actos anteriores o simultáneos.","Inducen directamente a otro u otros a ejecutar el hecho.","Cooperan a su ejecución con un acto sin el cual no se habría efectuado.","Realizan el hecho por medio de otro del que se sirven como instrumento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cooperan a la ejecución del hecho con actos anteriores o simultáneos</mark></span>El <span class=\"ref-norma\">art. 29 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Son cómplices los que, no hallándose comprendidos en el artículo anterior, cooperan a la ejecución del hecho con actos anteriores o simultáneos\"</span>"}]},{"a":"Artículo 35 ✱ R17","q":[{"i":"18-7","p":"Código Penal. De las penas, sus clases y efectos. Son penas privativas de libertad: señale la INCORRECTA.","o":["La prisión permanente revisable.","La prisión.","La localización permanente.","La inhabilitación absoluta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La inhabilitación absoluta</mark></span>La responsabilidad personal subsidiaria por impago de multa SÍ es pena privativa de libertad; la inhabilitación absoluta es privativa de derechos. Según el <span class=\"ref-norma\">art. 35 del Código Penal</span>: <span class=\"ref-concepto\">\"Son penas privativas de libertad la prisión permanente revisable, la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa\"</span> (verificado con el texto del temario oficial)."},{"i":"18-197","p":"Código Penal. ¿Cuáles son las penas privativas de libertad? Señale la INCORRECTA.","o":["La prisión temporal revisable.","La prisión.","La localización permanente.","La responsabilidad personal subsidiaria por impago de multa. *"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La prisión temporal revisable</mark></span>La pena es «prisión permanente revisable», no «temporal»; la responsabilidad personal subsidiaria por impago de multa sí es privativa de libertad. Según el <span class=\"ref-norma\">art. 35 del Código Penal</span>: <span class=\"ref-concepto\">\"Son penas privativas de libertad la prisión permanente revisable, la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1154","p":"Código Penal. Penas privativas de libertad. Son penas privativas de libertad:","o":["la prisión permanente revisable, la prisión y la localización permanente.","la prisión, la localización permanente y los trabajos en beneficio de la comunidad.","la prisión permanente revisable, la prisión, la localización permanente y los arrestos de fin de semana, salvo que la autoridad judicial disponga otra cosa.","la prisión permanente revisable, la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la prisión permanente revisable, la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa</mark></span>El <span class=\"ref-norma\">art. 35 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Son penas privativas de libertad la prisión permanente revisable, la prisión, la localización permanente y la responsabilidad personal subsidiaria por impago de multa\"</span>. Cuatro penas privativas de libertad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 36","q":[{"i":"18-ia-1156","p":"Código Penal. Prisión permanente revisable. El condenado a prisión permanente revisable por un delito de terrorismo del Capítulo VII del Título XXII del Libro II no podrá ser clasificado en el tercer grado hasta el cumplimiento de:","o":["quince años de prisión efectiva.","veinte años de prisión efectiva.","veinticinco años de prisión efectiva.","diecisiete años de prisión efectiva."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">veinte años de prisión efectiva</mark></span>El <span class=\"ref-norma\">art. 36.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Hasta el cumplimiento de veinte años de prisión efectiva, en el caso de que el penado lo hubiera sido por un delito del Capítulo VII del Título XXII del Libro II de este Código\"</span>. Veinte años de prisión efectiva en terrorismo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1203","p":"Código Penal. Pena de prisión. La clasificación del condenado en el tercer grado deberá ser autorizada por el tribunal previo pronóstico individualizado y favorable de reinserción social, oídos el Ministerio Fiscal e Instituciones Penitenciarias, y no podrá efectuarse hasta el cumplimiento de __________ años de prisión efectiva, en el caso de que el penado lo hubiera sido por un delito del Capítulo VII del Título XXII del Libro II:","o":["quince, en los términos que se determinen reglamentariamente.","doce","veinte","ocho"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">veinte</mark></span>El <span class=\"ref-norma\">art. 36.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no podrá efectuarse: a) Hasta el cumplimiento de veinte años de prisión efectiva, en el caso de que el penado lo hubiera sido por un delito del Capítulo VII del Título XXII del Libro II de este Código\"</span>. Veinte años para los delitos de terrorismo; quince años en el resto de los casos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1155","p":"Código Penal. Prisión permanente revisable. La clasificación del condenado a prisión permanente revisable en el tercer grado deberá ser autorizada por el tribunal previo pronóstico individualizado y favorable de reinserción social, oídos el Ministerio Fiscal e Instituciones Penitenciarias, y no podrá efectuarse hasta el cumplimiento de __________ años de prisión efectiva en el resto de los casos distintos del terrorismo:","o":["veinte","dieciocho","quince","doce"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">quince</mark></span>El <span class=\"ref-norma\">art. 36.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) Hasta el cumplimiento de quince años de prisión efectiva, en el resto de los casos\"</span>. Quince años en general; veinte años en terrorismo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1204","p":"Código Penal. Pena de prisión. En los supuestos en que el tercer grado no pueda efectuarse hasta el cumplimiento de quince años de prisión efectiva, el penado no podrá disfrutar de permisos de salida hasta que haya cumplido un mínimo de:","o":["doce años de prisión.","ocho años de prisión.","diez años de prisión.","cinco años de prisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ocho años de prisión</mark></span>El <span class=\"ref-norma\">art. 36.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el penado no podrá disfrutar de permisos de salida hasta que haya cumplido un mínimo de doce años de prisión, en el caso previsto en la letra a), y ocho años de prisión, en el previsto en la letra b)\"</span>. Doce años en el caso de la letra a) (veinte años) y ocho años en el de la letra b) (quince años). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1157","p":"Código Penal. Prisión permanente revisable. En los supuestos de prisión permanente revisable, el penado no podrá disfrutar de permisos de salida hasta que haya cumplido un mínimo de doce años de prisión, en el caso de terrorismo, y de:","o":["ocho años de prisión, en el resto de los casos.","diez años de prisión, en el resto de los casos, previo informe de la unidad policial competente.","ocho años de prisión, en todo caso.","doce años de prisión, en el resto de los casos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ocho años de prisión, en el resto de los casos</mark></span>El <span class=\"ref-norma\">art. 36.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el penado no podrá disfrutar de permisos de salida hasta que haya cumplido un mínimo de doce años de prisión, en el caso previsto en la letra a), y ocho años de prisión, en el previsto en la letra b)\"</span>. Permisos: doce años en terrorismo y ocho años en el resto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-262","p":"Código Penal. Pena de prisión. La pena de prisión tendrá una duración mínima de tres meses y máxima de:","o":["Quince años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código.","Veinticinco años, salvo lo que excepcionalmente dispongan las leyes penales especiales.","Veinte años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código.","Treinta años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Veinte años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código</mark></span>El <span class=\"ref-norma\">art. 36.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La pena de prisión tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código\"</span>"},{"i":"18-ia-1158","p":"Código Penal. Pena de prisión. La pena de prisión tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que:","o":["acuerde motivadamente el Juez de Vigilancia Penitenciaria, sin perjuicio de lo previsto en la normativa vigente.","establezca la sentencia por razones de peligrosidad.","disponga el Reglamento Penitenciario.","excepcionalmente dispongan otros preceptos del presente Código."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">excepcionalmente dispongan otros preceptos del presente Código</mark></span>El <span class=\"ref-norma\">art. 36.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena de prisión tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código\"</span>. Mínimo tres meses y máximo veinte años, con excepciones legales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1201","p":"Código Penal. Pena de prisión. La pena de prisión tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que excepcionalmente dispongan:","o":["otros preceptos del presente Código.","las leyes penales especiales.","los tratados internacionales ratificados por España.","las sentencias del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">otros preceptos del presente Código</mark></span>El <span class=\"ref-norma\">art. 36.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"La pena de prisión tendrá una duración mínima de tres meses y máxima de veinte años, salvo lo que excepcionalmente dispongan otros preceptos del presente Código\"</span>. La salvedad se refiere a otros preceptos del propio Código Penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1159","p":"Código Penal. Pena de prisión. Cuando la duración de la pena de prisión impuesta sea superior a cinco años, el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de:","o":["dos tercios de la pena impuesta.","tres cuartas partes de la pena impuesta.","la mitad de la pena impuesta.","la mitad de la pena, en todo caso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la mitad de la pena impuesta</mark></span>El <span class=\"ref-norma\">art. 36.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de la mitad de la pena impuesta\"</span>. Periodo de seguridad facultativo: la mitad de la pena. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1202","p":"Código Penal. Pena de prisión. Cuando la duración de la pena de prisión impuesta sea superior a cinco años, el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de:","o":["los dos tercios de la pena impuesta.","las tres cuartas partes de la pena impuesta.","la mitad de la pena, descontado el tiempo de prisión provisional.","la mitad de la pena impuesta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la mitad de la pena impuesta</mark></span>El <span class=\"ref-norma\">art. 36.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de la mitad de la pena impuesta\"</span>. Es la mitad de la pena impuesta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-208","p":"Código Penal. ¿Cómo ha de ser el pronóstico de reinserción social de la autoridad judicial de vigilancia penitenciaria, para que pueda acordar razonadamente la aplicación del régimen general de cumplimiento? Indique la INCORRECTA:","o":["Previo","Individualizado","Subjetivo","Favorable"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Subjetivo</mark></span>(El pronóstico debe ser &quot;favorable&quot;, &quot;individualizado&quot; y &quot;fundamentado&quot;, pero no se exige que sea &quot;subjetivo&quot; como característica legal. Se basa en un análisis objetivo)."},{"i":"18-ia-1161","p":"Código Penal. Régimen general de cumplimiento. La autoridad judicial de vigilancia penitenciaria podrá acordar razonadamente, previo pronóstico individualizado y favorable de reinserción social, oídos el Ministerio Fiscal, Instituciones Penitenciarias y las demás partes, la aplicación del régimen general de cumplimiento, salvo en:","o":["los supuestos contenidos en el apartado anterior.","los delitos cometidos contra menores de edad.","los casos en que la pena sea superior a diez años.","los delitos de terrorismo exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los supuestos contenidos en el apartado anterior</mark></span>El <span class=\"ref-norma\">art. 36.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la aplicación del régimen general de cumplimiento, salvo en los supuestos contenidos en el apartado anterior\"</span>. No procede en los supuestos del apartado anterior (periodo de seguridad obligatorio). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1206","p":"Código Penal. Pena de prisión. La autoridad judicial de vigilancia penitenciaria podrá acordar, previo informe del Ministerio Fiscal, Instituciones Penitenciarias y las demás partes, la progresión a tercer grado por motivos humanitarios y de dignidad personal de las personas condenadas enfermas muy graves con padecimientos incurables y de las personas:","o":["mayores de sesenta y cinco años.","octogenarias.","mayores de sesenta años con padecimientos crónicos.","septuagenarias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">septuagenarias</mark></span>El <span class=\"ref-norma\">art. 36.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"de las personas condenadas enfermas muy graves con padecimientos incurables y de las personas septuagenarias, valorando, especialmente, su escasa peligrosidad\"</span>. Septuagenarias, valorando especialmente su escasa peligrosidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-220","p":"Código Penal. En todo caso, la autoridad judicial de vigilancia penitenciaria, según corresponda, podrá acordar la progresión a tercer grado, con los informes de ¿Quién? Indique la opción INCORRECTA:","o":["El Ministerio Fiscal","El Tribunal competente","Las demás partes","Instituciones Penitenciarias"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Tribunal competente</mark></span>Los informes son del Ministerio Fiscal, Instituciones Penitenciarias y las demás partes; no de «el Tribunal competente». Según el <span class=\"ref-norma\">art. 36 del Código Penal</span>: <span class=\"ref-concepto\">\"podrá acordar, previo informe del Ministerio Fiscal, Instituciones Penitenciarias y las demás partes, la progresión a tercer grado por motivos humanitarios y de dignidad personal\"</span> (verificado con el texto del temario oficial)."},{"i":"18-239","p":"Código Penal. ¿Qué se valorará, especialmente, cuando la autoridad judicial de vigilancia penitenciaria, según corresponda, acuerde la progresión a tercer grado por motivos humanitarios y de dignidad personal de las personas condenadas enfermas muy graves con padecimientos incurables y de las personas septuagenarias?","o":["Su gravedad.","Su duración.","Su escasa peligrosidad.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Su escasa peligrosidad</mark></span>Solo se valora la escasa peligrosidad (no la gravedad ni la duración). Según el <span class=\"ref-norma\">art. 36 del Código Penal</span>: <span class=\"ref-concepto\">\"podrá acordar, previo informe del Ministerio Fiscal, Instituciones Penitenciarias y las demás partes, la progresión a tercer grado por motivos humanitarios y de dignidad personal de las personas condenadas enfermas muy graves con padecimientos incurables y de las personas septuagenarias, valorando, especialmente, su escasa peligrosidad\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1162","p":"Código Penal. Progresión a tercer grado humanitaria. En todo caso, la autoridad judicial de vigilancia penitenciaria, previo informe del Ministerio Fiscal, Instituciones Penitenciarias y las demás partes, podrá acordar la progresión a tercer grado por motivos humanitarios y de dignidad personal de las personas condenadas enfermas muy graves con padecimientos incurables y de las personas:","o":["mayores de ochenta años, valorando su edad avanzada.","septuagenarias, siempre que hayan cumplido la mitad de la condena.","sexagenarias, valorando, especialmente, su escasa peligrosidad.","septuagenarias, valorando, especialmente, su escasa peligrosidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">septuagenarias, valorando, especialmente, su escasa peligrosidad</mark></span>El <span class=\"ref-norma\">art. 36.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"y de las personas septuagenarias, valorando, especialmente, su escasa peligrosidad\"</span>. Septuagenarias y enfermos muy graves con padecimientos incurables, valorando su escasa peligrosidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 39","q":[{"i":"18-186","p":"Código Penal. Son penas privativas de derechos:","o":["La delegación de la patria potestad.","Los trabajos con ánimo de lucro para la comunidad.","La suspensión de empleo o cargo público.","La inhabilitación permanente. *"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La suspensión de empleo o cargo público.</mark></span><span class=\"ref-norma\">Art. 39 · De las Penas</span>. La suspensión de empleo o cargo público. (Las penas privativas de derechos se enumeran en el Artículo 39 del Código Penal. Los &quot;trabajos en beneficio de la comunidad&quot; no son con ánimo de lucro, y la &quot;inhabilitación especial&quot; es temporal, no permanente).*"},{"i":"18-230","p":"Código Penal. Son penas privativas de derechos:","o":["La prisión permanente revisable","La prisión","Los trabajos en beneficio de la comunidad","Todas son correctas"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los trabajos en beneficio de la comunidad</mark></span><span class=\"ref-norma\">Art. 39 · De las Penas</span>. (Los trabajos en beneficio de la comunidad son penas privativas de derechos según el Artículo 39 del CP. Las opciones a y b son penas privativas de libertad)."}]},{"a":"Artículo 50 R19 R20","q":[{"i":"18-263","p":"Código Penal. Pena de multa. La pena de multa consistirá en:","o":["La imposición al condenado de una sanción administrativa de naturaleza pecuniaria.","La imposición al condenado de una sanción pecuniaria.","El pago de la cantidad que fije el Ministerio Fiscal en su escrito de acusación.","La privación de determinados bienes del condenado a favor del Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La imposición al condenado de una sanción pecuniaria</mark></span>El <span class=\"ref-norma\">art. 50.1 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"La pena de multa consistirá en la imposición al condenado de una sanción pecuniaria\"</span>"},{"i":"18-55","p":"Código Penal. De la pena multa. Señale la CORRECTA","o":["La pena de multa se impondrá, salvo que la Ley disponga otra cosa, por el sistema de días-multa","Las penas de multa impuestas a personas jurídicas tendrán una extensión máxima de cuatro años","La cuota diaria tendrá un mínimo de dos y un máximo de 300 euros","Ninguna es correcta"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La pena de multa se impondrá, salvo que la Ley disponga otra cosa, por el sistema de días-multa</mark></span>- El sistema de días-multa es el sistema general para la imposición de multas."},{"i":"18-ia-1236","p":"Código Penal. Pena de multa. A efectos de cómputo, cuando se fije la duración de la multa por meses o por años, se entenderá que:","o":["los meses son de treinta días y los años de trescientos sesenta y cinco.","los meses son de treinta días y los años de trescientos sesenta.","los meses son de treinta y un días y los años de trescientos sesenta.","los meses son naturales y los años de trescientos sesenta y cinco."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los meses son de treinta días y los años de trescientos sesenta</mark></span>El <span class=\"ref-norma\">art. 50.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se entenderá que los meses son de treinta días y los años de trescientos sesenta\"</span>. Meses de treinta días y años de trescientos sesenta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-222","p":"Código Penal. Sobre la pena de multa. A efectos de cómputo, cuando se fije la duración por meses o por años, se entenderá que los años son de ¿Cuántos días? Indique la CORRECTA:","o":["Trescientos sesenta días","Trescientos sesenta y cinco días","Trescientos sesenta y un día","Trescientos sesenta y seis días"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Trescientos sesenta días</mark></span>Los años se computan de trescientos sesenta días (no 365). Según el <span class=\"ref-norma\">art. 50 del Código Penal</span>: <span class=\"ref-concepto\">\"se entenderá que los meses son de treinta días y los años de trescientos sesenta\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1237","p":"Código Penal. Pena de multa. Los Jueces o Tribunales fijarán en la sentencia el importe de las cuotas diarias, teniendo en cuenta para ello exclusivamente:","o":["la situación económica del reo, deducida de su patrimonio, ingresos, obligaciones y cargas familiares y demás circunstancias personales del mismo.","la gravedad del delito cometido, el beneficio obtenido y la situación económica del reo.","los ingresos del reo y el perjuicio causado a la víctima por el delito.","la situación económica del reo, valorada junto con las circunstancias atenuantes y agravantes, sin perjuicio de lo previsto en la normativa vigente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la situación económica del reo, deducida de su patrimonio, ingresos, obligaciones y cargas familiares y demás circunstancias personales del mismo</mark></span>El <span class=\"ref-norma\">art. 50.5 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"teniendo en cuenta para ello exclusivamente la situación económica del reo, deducida de su patrimonio, ingresos, obligaciones y cargas familiares y demás circunstancias personales del mismo\"</span>. Exclusivamente la situación económica del reo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1238","p":"Código Penal. Pena de multa. El tribunal, por causa justificada, podrá autorizar el pago de la multa dentro de un plazo que no exceda de __________ desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen. En este caso, el impago de dos de ellos determinará el vencimiento de los restantes:","o":["un año","tres años","seis meses","dos años"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos años</mark></span>El <span class=\"ref-norma\">art. 50.6 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá autorizar el pago de la multa dentro de un plazo que no exceda de dos años desde la firmeza de la sentencia, bien de una vez o en los plazos que se determinen. En este caso, el impago de dos de ellos determinará el vencimiento de los restantes\"</span>. Dos años desde la firmeza; el impago de dos plazos vence los restantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 62 R22","q":[{"i":"18-265","p":"Código Penal. Penas de la tentativa. A los autores de tentativa de delito se les impondrá:","o":["La pena inferior en un solo grado a la señalada por la Ley para el delito consumado, en la extensión que se estime adecuada, salvo que el órgano competente acuerde otra cosa de forma motivada.","La pena inferior en dos grados a la señalada por la Ley para el delito consumado, en todo caso.","La misma pena que a los autores del delito consumado, en su mitad inferior.","La pena inferior en uno o dos grados a la señalada por la Ley para el delito consumado, en la extensión que se estime adecuada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La pena inferior en uno o dos grados a la señalada por la Ley para el delito consumado, en la extensión que se estime adecuada</mark></span>El <span class=\"ref-norma\">art. 62 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"A los autores de tentativa de delito se les impondrá la pena inferior en uno o dos grados a la señalada por la Ley para el delito consumado, en la extensión que se estime adecuada\"</span>"},{"i":"18-ia-1262","p":"Código Penal. Reglas generales para la aplicación de las penas. A los autores de tentativa de delito se les impondrá la pena inferior en uno o dos grados a la señalada por la Ley para el delito consumado, en la extensión que se estime adecuada, atendiendo:","o":["a la gravedad del hecho y a las circunstancias personales del autor.","al daño causado y a la voluntad del autor de consumar el delito.","al resultado producido y a la peligrosidad del autor.","al peligro inherente al intento y al grado de ejecución alcanzado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al peligro inherente al intento y al grado de ejecución alcanzado</mark></span>El <span class=\"ref-norma\">art. 62 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"atendiendo al peligro inherente al intento y al grado de ejecución alcanzado\"</span>. Peligro inherente al intento y grado de ejecución alcanzado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 63 R23","q":[{"i":"18-266","p":"Código Penal. Penas de la complicidad. A los cómplices de un delito consumado o intentado se les impondrá:","o":["La pena inferior en uno o dos grados a la fijada por la Ley para los autores del mismo delito.","La misma pena que a los autores, en su mitad inferior.","La pena inferior en grado a la fijada por la Ley para los autores del mismo delito.","La pena inferior en grado a la señalada para el delito consumado, solo si éste se hubiera consumado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La pena inferior en grado a la fijada por la Ley para los autores del mismo delito</mark></span>El <span class=\"ref-norma\">art. 63 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"A los cómplices de un delito consumado o intentado se les impondrá la pena inferior en grado a la fijada por la Ley para los autores del mismo delito\"</span>"},{"i":"18-ia-1263","p":"Código Penal. Reglas generales para la aplicación de las penas. A los cómplices de un delito consumado o intentado se les impondrá:","o":["la pena inferior en uno o dos grados a la fijada por la Ley para los autores del mismo delito.","la misma pena que a los autores, en su mitad inferior.","la pena inferior en grado a la fijada por la Ley para los autores del mismo delito.","la pena inferior en grado a la señalada para el delito consumado, solo si éste se hubiese ejecutado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la pena inferior en grado a la fijada por la Ley para los autores del mismo delito</mark></span>El <span class=\"ref-norma\">art. 63 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los cómplices de un delito consumado o intentado se les impondrá la pena inferior en grado a la fijada por la Ley para los autores del mismo delito\"</span>. Pena inferior en grado a la de los autores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 69","q":[{"i":"18-269","p":"Código Penal. Mayores de dieciocho y menores de veintiún años. Al mayor de dieciocho años y menor de veintiuno que cometa un hecho delictivo, podrán aplicársele las disposiciones de:","o":["La Ley de Enjuiciamiento Criminal relativas al procedimiento para el enjuiciamiento rápido de delitos, sin perjuicio de lo que establezcan los tratados internacionales.","La ley penitenciaria, con cumplimiento de la pena en centros específicos para jóvenes.","La ley que regule la responsabilidad penal del menor, en todo caso y sin requisitos.","La ley que regule la responsabilidad penal del menor en los casos y con los requisitos que ésta disponga."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La ley que regule la responsabilidad penal del menor en los casos y con los requisitos que ésta disponga</mark></span>El <span class=\"ref-norma\">art. 69 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Al mayor de dieciocho años y menor de veintiuno que cometa un hecho delictivo, podrán aplicársele las disposiciones de la ley que regule la responsabilidad penal del menor en los casos y con los requisitos que ésta disponga\"</span>"},{"i":"18-ia-1305","p":"Código Penal. Mayores de dieciocho y menores de veintiún años. Al mayor de dieciocho años y menor de veintiuno que cometa un hecho delictivo, podrán aplicársele las disposiciones de:","o":["la ley que regule la responsabilidad penal del menor en los casos y con los requisitos que ésta disponga.","la ley de enjuiciamiento criminal relativas al procedimiento abreviado en todo caso, sin perjuicio de lo previsto en la normativa vigente.","la ley que regule la responsabilidad penal del menor, siempre y en todo caso.","la ley penitenciaria, con cumplimiento de la pena en centros de menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la ley que regule la responsabilidad penal del menor en los casos y con los requisitos que ésta disponga</mark></span>El <span class=\"ref-norma\">art. 69 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrán aplicársele las disposiciones de la ley que regule la responsabilidad penal del menor en los casos y con los requisitos que ésta disponga\"</span>. Podrán aplicarse en los casos y con los requisitos que la ley disponga. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"PRISIÓN PERMANENTE REVISABLE · acceso al tercer grado y suspensión (cuadro a mano de tu temario · art. 78 bis)","q":[{"i":"18-ia-1331","p":"Código Penal. Beneficios penitenciarios y cumplimiento. Si a consecuencia de las limitaciones establecidas para el máximo de cumplimiento la pena a cumplir resultase inferior a la mitad de la suma total de las impuestas, el juez o tribunal sentenciador podrá acordar que los beneficios penitenciarios, los permisos de salida, la clasificación en tercer grado y el cómputo de tiempo para la libertad condicional se refieran:","o":["a la mitad de las penas impuestas en las sentencias.","a las dos terceras partes del límite máximo de cumplimiento.","a la totalidad de las penas impuestas en las sentencias.","únicamente a la pena más grave de las impuestas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a la totalidad de las penas impuestas en las sentencias</mark></span>El <span class=\"ref-norma\">art. 78.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se refieran a la totalidad de las penas impuestas en las sentencias\"</span>. Se refieren a la totalidad de las penas impuestas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1332","p":"Código Penal. Beneficios penitenciarios y cumplimiento. En los delitos de terrorismo o cometidos en el seno de organizaciones criminales, y atendiendo a la suma total de las penas impuestas, la posibilidad de aplicar el régimen general de cumplimiento sólo será aplicable al tercer grado penitenciario cuando quede por cumplir:","o":["una octava parte del límite máximo de cumplimiento de la condena, en los términos que se determinen reglamentariamente.","una quinta parte del límite máximo de cumplimiento de la condena.","una cuarta parte del límite máximo de cumplimiento de la condena.","una décima parte del límite máximo de cumplimiento de la condena."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una quinta parte del límite máximo de cumplimiento de la condena</mark></span>El <span class=\"ref-norma\">art. 78.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Al tercer grado penitenciario, cuando quede por cumplir una quinta parte del límite máximo de cumplimiento de la condena\"</span>. Tercer grado: una quinta parte; libertad condicional: una octava parte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1333","p":"Código Penal. Beneficios penitenciarios y cumplimiento. En los delitos de terrorismo o cometidos en el seno de organizaciones criminales, la posibilidad de aplicar el régimen general de cumplimiento sólo será aplicable a la libertad condicional cuando quede por cumplir:","o":["una octava parte del límite máximo de cumplimiento de la condena.","una quinta parte del límite máximo de cumplimiento de la condena, salvo que la autoridad judicial disponga otra cosa.","una décima parte del límite máximo de cumplimiento de la condena.","una cuarta parte del límite máximo de cumplimiento de la condena."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una octava parte del límite máximo de cumplimiento de la condena</mark></span>El <span class=\"ref-norma\">art. 78.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) A la libertad condicional, cuando quede por cumplir una octava parte del límite máximo de cumplimiento de la condena\"</span>. Una octava parte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1334","p":"Código Penal. Prisión permanente revisable y acceso a tercer grado. Cuando el penado lo haya sido por varios delitos, uno de ellos castigado con prisión permanente revisable, y el resto de las penas impuestas sumen un total que exceda de cinco años, la progresión a tercer grado requerirá el cumplimiento de un mínimo de:","o":["veinte años de prisión.","veintidós años de prisión, previo informe de la unidad policial competente.","quince años de prisión.","dieciocho años de prisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dieciocho años de prisión</mark></span>El <span class=\"ref-norma\">art. 78 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) de un mínimo de dieciocho años de prisión, cuando el penado lo haya sido por varios delitos, uno de ellos esté castigado con pena de prisión permanente revisable y el resto de las penas impuestas sumen un total que exceda de cinco años\"</span>. 18 años (resto > 5 años); 20 años (resto > 15 años); 22 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1335","p":"Código Penal. Prisión permanente revisable y acceso a tercer grado. Cuando el penado lo haya sido por varios delitos, uno de ellos castigado con prisión permanente revisable y el resto de las penas impuestas sumen un total que exceda de quince años, la progresión a tercer grado requerirá un mínimo de:","o":["dieciocho años de prisión.","veintidós años de prisión.","veinte años de prisión.","veinticinco años de prisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">veinte años de prisión</mark></span>El <span class=\"ref-norma\">art. 78 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"b) de un mínimo de veinte años de prisión, cuando el penado lo haya sido por varios delitos, uno de ellos esté castigado con una pena de prisión permanente revisable y el resto de las penas impuestas sumen un total que exceda de quince años\"</span>. 20 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1336","p":"Código Penal. Prisión permanente revisable y acceso a tercer grado. La progresión a tercer grado requerirá el cumplimiento de un mínimo de veintidós años de prisión cuando el penado lo haya sido por varios delitos y:","o":["dos o más de ellos estén castigados con prisión permanente revisable, o uno lo esté y el resto de penas sumen un total superior a quince años, sin perjuicio de lo previsto en la normativa vigente.","dos o más de ellos estén castigados con una pena de prisión permanente revisable, o bien uno lo esté y el resto de penas impuestas sumen un total de veinticinco años o más.","uno de ellos esté castigado con prisión permanente revisable y el resto de las penas sumen un total de veinte años o más.","tres o más de ellos estén castigados con prisión permanente revisable."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dos o más de ellos estén castigados con una pena de prisión permanente revisable, o bien uno lo esté y el resto de penas impuestas sumen un total de veinticinco años o más</mark></span>El <span class=\"ref-norma\">art. 78 bis.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"c) de un mínimo de veintidós años de prisión, cuando el penado lo haya sido por varios delitos y dos o más de ellos estén castigados con una pena de prisión permanente revisable, o bien uno de ellos esté castigado con una pena de prisión permanente revisable y el resto de penas impuestas sumen un total de veinticinco años o más\"</span>. 22 años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1337","p":"Código Penal. Prisión permanente revisable y acceso a tercer grado. En los supuestos de las letras a) y b), la suspensión de la ejecución del resto de la pena requerirá que el penado haya extinguido un mínimo de:","o":["veinticinco años de prisión.","veintidós años de prisión, en los términos que se determinen reglamentariamente.","treinta años de prisión.","veinte años de prisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">veinticinco años de prisión</mark></span>El <span class=\"ref-norma\">art. 78 bis.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"a) Un mínimo de veinticinco años de prisión, en los supuestos a los que se refieren las letras a) y b) del apartado anterior\"</span>. 25 años (letras a y b); 30 años (letra c). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1338","p":"Código Penal. Prisión permanente revisable y acceso a tercer grado. Si se tratase de delitos de terrorismo o cometidos en el seno de organizaciones criminales, los límites mínimos de cumplimiento para el acceso al tercer grado serán de veinticuatro años de prisión en los supuestos de las letras a) y b), y de:","o":["treinta años de prisión en el de la letra c).","treinta y cinco años de prisión en el de la letra c).","veintiocho años de prisión en el de la letra c).","treinta y dos años de prisión en el de la letra c)."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">treinta y dos años de prisión en el de la letra c)</mark></span>El <span class=\"ref-norma\">art. 78 bis.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"serán de veinticuatro años de prisión, en los supuestos a que se refieren las letras a) y b) del apartado primero, y de treinta y dos años de prisión en el de la letra c) del apartado primero\"</span>. 24 años (a y b) y 32 años (c). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Art. 97 CP · Durante la ejecución de la sentencia","q":[{"i":"18-160","p":"Código Penal. De las medidas de seguridad en general, ¿Cuál de las siguientes decisiones puede tomar el Juez o Tribunal sentenciador durante la ejecución de la sentencia?","o":["Mantener la ejecución de la medida de seguridad impuesta.","Decretar el cese de cualquier medida de seguridad impuesta en cuanto desaparezca la peligrosidad criminal del sujeto.","Sustituir una medida de seguridad por otra que estime más adecuada, entre las previstas para el supuesto de que se trate.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 97 del Código Penal</span>: <span class=\"ref-concepto\">\"c) Sustituir una medida de seguridad por otra que estime más adecuada, entre las previstas para el supuesto de que se trate\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1345","p":"Código Penal. Ejecución de las medidas de seguridad. Durante la ejecución de la sentencia, el Juez o Tribunal sentenciador podrá decretar el cese de cualquier medida de seguridad impuesta en cuanto:","o":["desaparezca la peligrosidad criminal del sujeto.","transcurra la mitad del plazo máximo fijado en la sentencia.","lo solicite el sometido a la medida y lo informe el Ministerio Fiscal.","el sujeto haya cumplido la edad de setenta años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">desaparezca la peligrosidad criminal del sujeto</mark></span>El <span class=\"ref-norma\">art. 97 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"la peligrosidad criminal del sujeto\"</span>. Cese cuando desaparezca la peligrosidad criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1401","p":"Código Penal. Ejecución de las medidas de seguridad. El Juez o Tribunal sentenciador podrá dejar en suspenso la ejecución de la medida de seguridad en atención al resultado ya obtenido con su aplicación, por un plazo:","o":["no superior al que reste hasta el máximo señalado en la sentencia que la impuso.","no superior a la mitad del máximo señalado en la sentencia que la impuso.","no inferior al que reste hasta el máximo señalado en la sentencia que la impuso, en los términos que se determinen reglamentariamente.","no superior a cinco años en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no superior al que reste hasta el máximo señalado en la sentencia que la impuso</mark></span>El <span class=\"ref-norma\">art. 97.d del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"por un plazo no superior al que reste hasta el máximo señalado en la sentencia que la impuso\"</span>. Plazo no superior al que reste hasta el máximo señalado en la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1402","p":"Código Penal. Ejecución de las medidas de seguridad. La suspensión de la ejecución de la medida de seguridad quedará condicionada a que el sujeto no delinca durante el plazo fijado, y podrá dejarse sin efecto si:","o":["el sujeto no se presentara periódicamente ante el Juez de Vigilancia Penitenciaria, salvo que la autoridad judicial disponga otra cosa.","transcurriera la mitad del plazo de suspensión sin informe favorable.","lo solicitara el Ministerio Fiscal en cualquier momento.","nuevamente resultara acreditada cualquiera de las circunstancias previstas para su aplicación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">nuevamente resultara acreditada cualquiera de las circunstancias previstas para su aplicación</mark></span>El <span class=\"ref-norma\">art. 97.d del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"podrá dejarse sin efecto si nuevamente resultara acreditada cualquiera de las circunstancias previstas en el artículo 95 de este Código\"</span>. Si de nuevo se acreditan las circunstancias que justifican las medidas de seguridad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Art. 98 CP · Cuando una medida de seguridad deba ejecutarse DESPUÉS del cumplimiento de una pena privativa de libertad","q":[{"i":"18-ia-1403","p":"Código Penal. Procedimiento de ejecución de las medidas de seguridad. Cuando se trate de una medida de seguridad privativa de libertad o de una medida de libertad vigilada que deba ejecutarse después del cumplimiento de una pena privativa de libertad, el Juez de Vigilancia Penitenciaria estará obligado a elevar una propuesta de mantenimiento, cese, sustitución o suspensión de la misma:","o":["al menos semestralmente.","al menos cada dos años.","al menos anualmente.","al menos trimestralmente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al menos anualmente</mark></span>El <span class=\"ref-norma\">art. 98.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"estará obligado a elevar al menos anualmente, una propuesta de mantenimiento, cese, sustitución o suspensión de la misma\"</span>. Al menos anualmente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1404","p":"Código Penal. Procedimiento de ejecución de las medidas de seguridad. Cuando se trate de cualquier otra medida no privativa de libertad, el Juez o Tribunal sentenciador:","o":["recibirá la propuesta anual del Juez de Vigilancia Penitenciaria sobre el mantenimiento o cese de la medida, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","recabará directamente de las Administraciones, facultativos y profesionales los oportunos informes acerca de la situación y la evolución del condenado, su grado de rehabilitación y el pronóstico de reincidencia o reiteración delictiva.","recabará los informes por medio del Ministerio Fiscal, que los elevará con su propuesta.","resolverá sin necesidad de informes, oyendo únicamente a la persona sometida a la medida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">recabará directamente de las Administraciones, facultativos y profesionales los oportunos informes acerca de la situación y la evolución del condenado, su grado de rehabilitación y el pronóstico de reincidencia o reiteración delictiva</mark></span>El <span class=\"ref-norma\">art. 98.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el Juez o Tribunal sentenciador recabará directamente de las Administraciones, facultativos y profesionales a que se refiere el apartado anterior, los oportunos informes acerca de la situación y la evolución del condenado, su grado de rehabilitación y el pronóstico de reincidencia o reiteración delictiva\"</span>. Recaba directamente los informes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1405","p":"Código Penal. Procedimiento de ejecución de las medidas de seguridad. En todo caso, el Juez o Tribunal sentenciador resolverá motivadamente a la vista de la propuesta o los informes, oída la propia persona sometida a la medida, así como el Ministerio Fiscal y las demás partes. Se oirá asimismo a las víctimas del delito:","o":["que no estuvieren personadas cuando así lo hubieran solicitado al inicio o en cualquier momento de la ejecución de la sentencia y permanezcan localizables a tal efecto.","que estuvieren personadas en el procedimiento, en todo caso.","que no estuvieren personadas, aunque no lo hubieran solicitado.","que lo soliciten expresamente antes de la sentencia y residan en España, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que no estuvieren personadas cuando así lo hubieran solicitado al inicio o en cualquier momento de la ejecución de la sentencia y permanezcan localizables a tal efecto</mark></span>El <span class=\"ref-norma\">art. 98.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"Se oirá asimismo a las víctimas del delito que no estuvieren personadas cuando así lo hubieran solicitado al inicio o en cualquier momento de la ejecución de la sentencia y permanezcan localizables a tal efecto\"</span>. Víctimas no personadas que lo hubieran solicitado y permanezcan localizables. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 105","q":[{"i":"18-278","p":"Código Penal. Medidas no privativas de libertad. Cuando imponga la medida privativa de libertad o durante la ejecución de la misma, el Juez o Tribunal podrá imponer razonadamente:","o":["Una única medida de las no privativas de libertad, previo informe del Ministerio Fiscal.","Una o varias penas accesorias de las previstas para las penas privativas de derechos.","Una o varias medidas que se enumeran a continuación.","Una medida no privativa de libertad, sin necesidad de razonarlo en la sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Una o varias medidas que se enumeran a continuación</mark></span>El <span class=\"ref-norma\">art. 105 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"el Juez o Tribunal podrá imponer razonadamente una o varias medidas que se enumeran a continuación\"</span>"},{"i":"18-ia-1418","p":"Código Penal. Medidas no privativas de libertad. Cuando el Juez o Tribunal imponga la medida privativa de libertad o durante la ejecución de la misma, podrá imponer razonadamente una o varias medidas no privativas. Por un tiempo no superior a cinco años podrá imponer:","o":["libertad vigilada y privación del derecho a la tenencia y porte de armas.","custodia familiar y privación del derecho a conducir vehículos a motor y ciclomotores.","libertad vigilada, exclusivamente.","libertad vigilada y custodia familiar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">libertad vigilada y custodia familiar</mark></span>El <span class=\"ref-norma\">art. 105.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"1. Por un tiempo no superior a cinco años: a) Libertad vigilada. b) Custodia familiar\"</span>. Hasta cinco años: libertad vigilada y custodia familiar; hasta diez años: libertad vigilada expresa, armas y conducir. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-279","p":"Código Penal. Medidas no privativas de libertad. Por un tiempo de hasta diez años, el Juez o Tribunal podrá imponer:","o":["Libertad vigilada y custodia familiar.","Libertad vigilada, cuando expresamente lo disponga el Código; privación del derecho a la tenencia y porte de armas y privación del derecho a conducir vehículos a motor y ciclomotores.","Custodia familiar y privación del derecho a la tenencia y porte de armas.","Inhabilitación profesional y privación del derecho a conducir vehículos a motor y ciclomotores, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Libertad vigilada, cuando expresamente lo disponga el Código; privación del derecho a la tenencia y porte de armas y privación del derecho a conducir vehículos a motor y ciclomotores</mark></span>El <span class=\"ref-norma\">art. 105.2 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"Por un tiempo de hasta diez años: a) Libertad vigilada, cuando expresamente lo disponga este Código. b) La privación del derecho a la tenencia y porte de armas. c) La privación del derecho a conducir vehículos a motor y ciclomotores\"</span>"},{"i":"18-ia-1419","p":"Código Penal. Medidas no privativas de libertad. Por un tiempo de hasta diez años, el Juez o Tribunal podrá imponer, entre otras, la privación del derecho a la tenencia y porte de armas, la privación del derecho a conducir vehículos a motor y ciclomotores y:","o":["la custodia familiar.","la inhabilitación profesional.","la libertad vigilada, cuando expresamente lo disponga este Código.","la expulsión del territorio nacional, salvo que la autoridad judicial disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la libertad vigilada, cuando expresamente lo disponga este Código</mark></span>El <span class=\"ref-norma\">art. 105.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"2. Por un tiempo de hasta diez años: a) Libertad vigilada, cuando expresamente lo disponga este Código\"</span>. Libertad vigilada cuando lo disponga expresamente el Código. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-47","p":"Código Penal. De las medidas de seguridad. Dentro de las medidas no privativas de libertad, ¿cuáles son las que se podrán imponer por un tiempo no superior a cinco años?","o":["Libertad vigilada.","Custodia familiar.","La privación del derecho a la tenencia y porte de armas.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Hasta cinco años: libertad vigilada y custodia familiar; hasta diez años: libertad vigilada (si lo dispone el Código), armas y conducir. Según el <span class=\"ref-norma\">art. 105 del Código Penal</span>: <span class=\"ref-concepto\">\"1. Por un tiempo no superior a cinco años: a) Libertad vigilada. b) Custodia familiar\"</span> (verificado con el texto del temario oficial)."}]},{"a":"Artículo 108 R24","q":[{"i":"18-29","p":"Código Penal. Si el sujeto fuera extranjero ______ el Juez o Tribunal acordará en la sentencia, previa audiencia de aquél, la expulsión del territorio nacional como sustitutiva de las medidas de seguridad que le sean aplicables, salvo que el Juez o Tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito justifica el cumplimiento en España.","o":["No residente legalmente en la Unión Europea.","Residentes legales en España.","No residente legalmente en España.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No residente legalmente en España.</mark></span>- La expulsión sustitutiva se aplica a extranjeros no residentes legalmente en España."},{"i":"18-74","p":"Código Penal. Si el condenado fuera extranjero no residente legalmente en España, el juez o tribunal acordará en la sentencia, previa audiencia de aquél, la expulsión del territorio nacional como sustitutiva de las medidas de seguridad que le sean aplicables, salvo que:","o":["El juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la desproporcionada de la expulsión del territorio nacional como condena con el delito cometido","El juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito justifica el cumplimiento en España","El juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito hace imposible el cumplimiento de la condena fuera de España","El juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la pena del delito es demasiado breve para considerar la expulsión del territorio nacional"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito just…</mark></span>- La expulsión puede no aplicarse cuando la naturaleza del delito justifique el cumplimiento en España."},{"i":"18-ia-1427","p":"Código Penal. Expulsión de extranjeros. Si el sujeto fuera extranjero no residente legalmente en España, el juez o tribunal acordará en la sentencia, previa audiencia de aquél, la expulsión del territorio nacional como sustitutiva de las medidas de seguridad que le sean aplicables, salvo que:","o":["el sujeto lo solicite y el Ministerio Fiscal informe favorablemente.","el delito cometido tenga señalada pena superior a cinco años de prisión, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente.","el juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito justifica el cumplimiento en España.","el Delegado del Gobierno se oponga motivadamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el juez o tribunal, previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito justifica el cumplimiento en España</mark></span>El <span class=\"ref-norma\">art. 108.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"previa audiencia del Ministerio Fiscal, excepcionalmente y de forma motivada, aprecie que la naturaleza del delito justifica el cumplimiento en España\"</span>. Excepcionalmente y de forma motivada, por la naturaleza del delito. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1428","p":"Código Penal. Expulsión de extranjeros. En el supuesto de que, acordada la sustitución de la medida de seguridad por la expulsión, ésta no pudiera llevarse a efecto:","o":["se declarará extinguida la medida de seguridad.","se procederá al cumplimiento de la medida de seguridad originariamente impuesta.","se impondrá la libertad vigilada por cinco años, salvo que la autoridad judicial disponga otra cosa.","se archivará el procedimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se procederá al cumplimiento de la medida de seguridad originariamente impuesta</mark></span>El <span class=\"ref-norma\">art. 108.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"ésta no pudiera llevarse a efecto, se procederá al cumplimiento de la medida de seguridad originariamente impuesta\"</span>. Se cumple la medida originariamente impuesta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1430","p":"Código Penal. Expulsión de extranjeros. El extranjero que intentara quebrantar una decisión judicial de expulsión y prohibición de entrada será devuelto por la autoridad gubernativa, empezando a computarse:","o":["el plazo de prohibición de entrada duplicado.","el plazo de prohibición de entrada desde la fecha de la devolución, descontado el ya transcurrido.","de nuevo el plazo de prohibición de entrada por la mitad.","de nuevo el plazo de prohibición de entrada en su integridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de nuevo el plazo de prohibición de entrada en su integridad</mark></span>El <span class=\"ref-norma\">art. 108.3 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"será devuelto por la autoridad gubernativa, empezando a computarse de nuevo el plazo de prohibición de entrada en su integridad\"</span>. Vuelve a computarse íntegramente el plazo de prohibición de entrada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 110","q":[{"i":"18-283","p":"Código Penal. Responsabilidad civil. La responsabilidad civil derivada del delito comprende:","o":["La restitución, la multa y las costas procesales.","La restitución, la reparación del daño y la indemnización de perjuicios materiales y morales.","La reparación del daño y la indemnización de los gastos de defensa del perjudicado.","La restitución y la indemnización de perjuicios materiales, con exclusión de los morales, conforme al procedimiento que reglamentariamente se establezca."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La restitución, la reparación del daño y la indemnización de perjuicios materiales y morales</mark></span>El <span class=\"ref-norma\">art. 110 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"º La restitución. 2.º La reparación del daño. 3.º La indemnización de perjuicios materiales y morales\"</span>"},{"i":"18-181","p":"Código penal. La responsabilidad civil comprende: señale la INCORRECTA.","o":["La reparación del daño.","La indemnización de perjuicios morales.","La restitución.","La indemnización de perjuicios económicos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La indemnización de perjuicios económicos</mark></span>Comprende restitución, reparación e indemnización de perjuicios materiales y morales; «perjuicios económicos» no es la expresión legal. Según el <span class=\"ref-norma\">art. 110 del Código Penal</span>: <span class=\"ref-concepto\">\"1.º La restitución. 2.º La reparación del daño. 3.º La indemnización de perjuicios materiales y morales\"</span> (verificado con el texto del temario oficial)."}]},{"a":"Artículo 114","q":[{"i":"18-28","p":"Código Penal. Si la víctima hubiere contribuido con su conducta a la producción del daño o perjuicio sufrido: señale la CORRECTA.","o":["Los Jueces o Tribunales podrán anular el importe de su reparación o indemnización.","Los Jueces o Tribunales podrán moderar el importe de su reparación o indemnización.","Los Jueces o Tribunales deberán moderar el importe de su reparación o indemnización.","Los Jueces o Tribunales no podrán modificar el importe de su reparación o indemnización."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Jueces o Tribunales podrán moderar el importe de su reparación o indemnización</mark></span>Según el <span class=\"ref-norma\">art. 114 del Código Penal</span>: <span class=\"ref-concepto\">\"los Jueces o Tribunales podrán moderar el importe de su reparación o indemnización\"</span> (verificado con el texto del temario oficial)."},{"i":"18-145","p":"Código Penal. ¿En qué situación los Jueces o Tribunales pueden moderar el importe de la reparación o indemnización?","o":["Si la víctima no contribuyó a la producción del daño.","Si la víctima contribuyó con su conducta al daño sufrido.","Si el daño fue causado por un tercero.","Si el daño es de naturaleza moral."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Si la víctima contribuyó con su conducta al daño sufrido.</mark></span>(Pueden moderar la indemnización cuando la víctima contribuyó con su conducta al daño)."},{"i":"18-ia-1437","p":"Código Penal. Responsabilidad civil. Si la víctima hubiere contribuido con su conducta a la producción del daño o perjuicio sufrido, los Jueces o Tribunales:","o":["podrán moderar el importe de su reparación o indemnización.","deberán excluir la reparación o indemnización.","reducirán en todo caso a la mitad la indemnización, previo informe de la unidad policial competente.","podrán imponerle el pago de las costas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrán moderar el importe de su reparación o indemnización</mark></span>El <span class=\"ref-norma\">art. 114 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"los Jueces o Tribunales podrán moderar el importe de su reparación o indemnización\"</span>. Podrán moderar el importe. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 130 R26","q":[{"i":"18-289","p":"Código Penal. Causas de extinción. Entre otras causas, la responsabilidad criminal se extingue:","o":["Por la reincidencia del condenado.","Por la libertad condicional del penado.","Por la revocación de la sentencia condenatoria.","Por la muerte del reo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por la muerte del reo</mark></span>El <span class=\"ref-norma\">art. 130.1 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"º Por la muerte del reo\"</span>"},{"i":"18-116","p":"Código Penal. La responsabilidad criminal se extingue:","o":["Por la muerte del reo.","Por el cumplimiento de la condena.","Por el perdón de la persona ofendida, cuando se trate de delitos leves perseguibles a instancia de la persona agraviada o la ley así lo prevea.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 130 del Código Penal</span>: <span class=\"ref-concepto\">\"5.º Por el perdón de la persona ofendida, cuando se trate de delitos leves perseguibles a instancias de la persona agraviada o la ley así lo prevea\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1529","p":"Código Penal. Causas de extinción de la responsabilidad criminal. El perdón de la persona ofendida, cuando se trate de delitos leves perseguibles a instancias de la persona agraviada o la ley así lo prevea, habrá de ser otorgado de forma expresa:","o":["antes de que se haya dictado sentencia, a cuyo efecto la autoridad judicial sentenciadora deberá oír a la persona ofendida por el delito antes de dictarla.","antes de la apertura del juicio oral, ante el Ministerio Fiscal.","hasta la firmeza de la sentencia, por escrito y ante el Secretario judicial.","antes de que se haya dictado sentencia, sin necesidad de audiencia a la persona ofendida, en los términos que se determinen reglamentariamente, salvo que la autoridad judicial disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">antes de que se haya dictado sentencia, a cuyo efecto la autoridad judicial sentenciadora deberá oír a la persona ofendida por el delito antes de dictarla</mark></span>El <span class=\"ref-norma\">art. 130.1.5.º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"El perdón habrá de ser otorgado de forma expresa antes de que se haya dictado sentencia, a cuyo efecto la autoridad judicial sentenciadora deberá oír a la persona ofendida por el delito antes de dictarla\"</span>. Expreso, antes de la sentencia y con audiencia de la ofendida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1530","p":"Código Penal. Causas de extinción de la responsabilidad criminal. En los delitos cometidos contra personas menores de edad o personas con discapacidad necesitadas de especial protección que afecten a bienes jurídicos eminentemente personales, el perdón de la persona ofendida:","o":["extingue la responsabilidad criminal si lo otorga su representante legal.","extingue la responsabilidad criminal si lo autoriza el Ministerio Fiscal.","solo extingue la responsabilidad criminal en los delitos leves.","no extingue la responsabilidad criminal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no extingue la responsabilidad criminal</mark></span>El <span class=\"ref-norma\">art. 130.1.5.º del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el perdón de la persona ofendida no extingue la responsabilidad criminal\"</span>. El perdón no extingue la responsabilidad criminal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1531","p":"Código Penal. Causas de extinción de la responsabilidad criminal. La transformación, fusión, absorción o escisión de una persona jurídica:","o":["extingue su responsabilidad penal, sin perjuicio de la responsabilidad civil.","extingue su responsabilidad penal si se produce antes de la apertura del juicio oral.","no extingue su responsabilidad penal, que se trasladará a la entidad o entidades en que se transforme, quede fusionada o absorbida y se extenderá a la entidad o entidades que resulten de la escisión.","no extingue su responsabilidad penal, que se trasladará únicamente a la entidad absorbente, previo informe de la unidad policial competente, sin perjuicio de lo previsto en la normativa vigente, en los términos que se determinen reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no extingue su responsabilidad penal, que se trasladará a la entidad o entidades en que se transforme, quede fusionada o absorbida y se extenderá a la entidad o entidades que resulten de la escisión</mark></span>El <span class=\"ref-norma\">art. 130.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"no extingue su responsabilidad penal, que se trasladará a la entidad o entidades en que se transforme, quede fusionada o absorbida y se extenderá a la entidad o entidades que resulten de la escisión\"</span>. No extingue la responsabilidad penal; se traslada a las entidades resultantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1532","p":"Código Penal. Causas de extinción de la responsabilidad criminal. Se considerará en todo caso que existe disolución encubierta o meramente aparente de la persona jurídica cuando se continúe su actividad económica y:","o":["se mantenga el mismo domicilio social y la misma denominación, salvo que la autoridad judicial disponga otra cosa, previo informe de la unidad policial competente.","se mantenga la identidad sustancial de clientes, proveedores y empleados, o de la parte más relevante de todos ellos.","se mantengan los mismos socios o administradores.","se mantenga el patrimonio de la sociedad disuelta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se mantenga la identidad sustancial de clientes, proveedores y empleados, o de la parte más relevante de todos ellos</mark></span>El <span class=\"ref-norma\">art. 130.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"cuando se continúe su actividad económica y se mantenga la identidad sustancial de clientes, proveedores y empleados, o de la parte más relevante de todos ellos\"</span>. Identidad sustancial de clientes, proveedores y empleados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 131 R27 R28","q":[{"i":"18-291","p":"Código Penal. Prescripción de los delitos. Los delitos prescriben a los veinte años, cuando la pena máxima señalada al delito sea:","o":["Prisión de más de diez años.","Prisión de quince o más años.","Prisión de veinte o más años.","Inhabilitación por más de diez años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Prisión de quince o más años</mark></span>El <span class=\"ref-norma\">art. 131.1 de la Código Penal</span> dispone: <span class=\"ref-concepto\">\"A los veinte años, cuando la pena máxima señalada al delito sea prisión de quince o más años\"</span>"},{"i":"18-ia-1533","p":"Código Penal. Prescripción de los delitos. Los delitos prescriben a los veinte años, cuando la pena máxima señalada al delito sea:","o":["prisión de quince o más años.","prisión de más de diez años.","prisión de veinte años.","inhabilitación por más de diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">prisión de quince o más años</mark></span>El <span class=\"ref-norma\">art. 131.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los veinte años, cuando la pena máxima señalada al delito sea prisión de quince o más años\"</span>. Veinte años: prisión de quince o más años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-146","p":"Código Penal. Prescripción de delitos. Prescriben a los veinte años:","o":["Cuando la pena máxima señalada al delito sea prisión de quince o más años.","Cuando la pena máxima señalada al delito sea inhabilitación por más de diez años.","Cuando la pena máxima señalada al delito sea prisión de veinte o más años.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando la pena máxima señalada al delito sea prisión de quince o más años.</mark></span>(Los delitos con pena máxima de 15 o más años de prisión prescriben a los 20 años)."},{"i":"18-177","p":"Código penal. Causas que extinguen la responsabilidad criminal. Los delitos prescriben:","o":["A los veinte años, cuando la pena máxima señalada al delito sea de quince o más años.","A los diez años, cuando la pena máxima señalada por la ley sea inhabilitación por más de diez años, o prisión por más de diez y menos de quince años.","A los cinco años, los demás delitos, excepto los delitos leves y los delitos de injurias y calumnias, que prescriben al año.","A los quince años, cuando la pena máxima señalada por la ley sea prisión o inhabilitación por más de cinco años y que no exceda de diez."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los veinte años, cuando la pena máxima señalada al delito sea de quince o más años.</mark></span>(Los delitos con pena máxima de 15+ años prescriben a los 20 años)."},{"i":"18-ia-1534","p":"Código Penal. Prescripción de los delitos. Los delitos prescriben a los quince años, cuando la pena máxima señalada por la ley sea:","o":["prisión o inhabilitación por más de cinco años y que no exceda de diez, sin perjuicio de lo previsto en la normativa vigente.","prisión de quince o más años.","inhabilitación por más de seis años.","inhabilitación por más de diez años, o prisión por más de diez y menos de quince años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">inhabilitación por más de diez años, o prisión por más de diez y menos de quince años</mark></span>El <span class=\"ref-norma\">art. 131.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los quince, cuando la pena máxima señalada por la ley sea inhabilitación por más de diez años, o prisión por más de diez y menos de quince años\"</span>. Quince años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1535","p":"Código Penal. Prescripción de los delitos. Los delitos prescriben a los diez años, cuando la pena máxima señalada por la ley sea:","o":["prisión por más de diez y menos de quince años.","prisión o inhabilitación por más de tres años y que no exceda de diez, en los términos que se determinen reglamentariamente.","prisión o inhabilitación por más de cinco años y que no exceda de diez.","prisión por más de cinco años y menos de quince."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">prisión o inhabilitación por más de cinco años y que no exceda de diez</mark></span>El <span class=\"ref-norma\">art. 131.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los diez, cuando la pena máxima señalada por la ley sea prisión o inhabilitación por más de cinco años y que no exceda de diez\"</span>. Diez años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-3","p":"Código Penal. Según establece el Código Penal, prescriben a los diez años los delitos de:","o":["Cuando la pena máxima señalada por la ley sea prisión de quince o más años.","Cuando la pena máxima señalada por la ley sea inhabilitación por más de cinco años y que no exceda de diez años.","Cuando la pena máxima señalada por la ley sea prisión por más de cinco años y que no exceda de diez años.","B y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">B y C son correctas</mark></span>Diez años: prisión o inhabilitación por más de cinco años y que no exceda de diez; veinte años: prisión de quince o más. Según el <span class=\"ref-norma\">art. 131 del Código Penal</span>: <span class=\"ref-concepto\">\"A los diez, cuando la pena máxima señalada por la ley sea prisión o inhabilitación por más de cinco años y que no exceda de diez\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1536","p":"Código Penal. Prescripción de los delitos. Los demás delitos prescriben a los cinco años, excepto los delitos leves y los delitos de injurias y calumnias, que prescriben:","o":["a los seis meses.","al año.","a los dos años.","a los tres años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al año</mark></span>El <span class=\"ref-norma\">art. 131.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"A los cinco, los demás delitos, excepto los delitos leves y los delitos de injurias y calumnias, que prescriben al año\"</span>. Al año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1537","p":"Código Penal. Prescripción de los delitos. Cuando la pena señalada por la ley fuere compuesta, se estará, para la aplicación de las reglas sobre prescripción de los delitos:","o":["a la que exija mayor tiempo para la prescripción.","a la que exija menor tiempo para la prescripción.","a la pena de mayor gravedad, sea cual sea el tiempo de prescripción.","a la pena inferior en grado de la señalada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la que exija mayor tiempo para la prescripción</mark></span>El <span class=\"ref-norma\">art. 131.2 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"se estará, para la aplicación de las reglas comprendidas en este artículo, a la que exija mayor tiempo para la prescripción\"</span>. La que exija mayor tiempo para la prescripción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"18-ia-1539","p":"Código Penal. Prescripción de los delitos. En los supuestos de concurso de infracciones o de infracciones conexas, el plazo de prescripción será:","o":["el que corresponda al delito menos grave.","el que corresponda a cada delito por separado.","el que corresponda al delito más grave.","el que resulte de sumar los plazos de cada delito."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el que corresponda al delito más grave</mark></span>El <span class=\"ref-norma\">art. 131.4 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"el plazo de prescripción será el que corresponda al delito más grave\"</span>. El del delito más grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 135 R29","q":[{"i":"18-104","p":"Código Penal. De la extinción de la responsabilidad criminal y sus efectos. Respecto de la prescripción de las medidas de seguridad, señale la CORRECTA:","o":["A los diez años, si fueran privativas de libertad de tres años o superior","A los cinco años, si fueran privativas de libertad iguales o inferiores a tres años","Al año, si tuvieran otro contenido","Ninguna es correcta"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los cinco años, si fueran privativas de libertad iguales o inferiores a tres años</mark></span>Diez años: privativas de libertad superiores a tres años; cinco años: las demás. Según el <span class=\"ref-norma\">art. 135 del Código Penal</span>: <span class=\"ref-concepto\">\"Las medidas de seguridad prescribirán a los diez años, si fueran privativas de libertad superiores a tres años, y a los cinco años si fueran privativas de libertad iguales o inferiores a tres años o tuvieran otro contenido\"</span> (verificado con el texto del temario oficial)."},{"i":"18-ia-1550","p":"Código Penal. Prescripción de las medidas de seguridad. Las medidas de seguridad prescribirán a los diez años, si fueran privativas de libertad superiores a tres años, y a los cinco años:","o":["si fueran no privativas de libertad exclusivamente.","si fueran privativas de libertad inferiores a tres años, salvo que la autoridad judicial disponga otra cosa.","en todo caso, cualquiera que sea su contenido.","si fueran privativas de libertad iguales o inferiores a tres años o tuvieran otro contenido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si fueran privativas de libertad iguales o inferiores a tres años o tuvieran otro contenido</mark></span>El <span class=\"ref-norma\">art. 135.1 del Código Penal</span> se dispone: <span class=\"ref-concepto\">\"y a los cinco años si fueran privativas de libertad iguales o inferiores a tres años o tuvieran otro contenido\"</span>. Cinco años: privativas de libertad iguales o inferiores a tres años u otro contenido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
